import pygame

def paddle_response(ball, paddle, vx, side):
    b, p = pygame.Rect(ball), pygame.Rect(paddle)
    if b.colliderect(p):
        if side == "left" and vx < 0:
            return (p.right, -vx)
        if side == "right" and vx > 0:
            return (p.left - b.width, -vx)
    return (b.left, vx)
